/* ════════ 晴空学院 Azure Academy · 卡兰大陆制卡师 ════════ */
/* 回复格式不变，仅美化外观 */

/* ── 正文容器：晴空下的学院手记 ── */
.markdown-body{
  font-family:'Georgia','Noto Serif SC','KaiTi','STKaiti',serif !important;
  color:#3a3320 !important;
  line-height:1.85 !important;
  padding:15px 17px !important;
  border-radius:6px !important;
  border:1px solid #a07d22 !important;
  background:
    radial-gradient(ellipse at 100% 0,rgba(176,138,40,.10),transparent 60%),
    radial-gradient(ellipse at 0 100%,rgba(176,138,40,.09),transparent 58%),
    linear-gradient(168deg,#f6f0d9,#f3ead2 70%,#f3ead2) !important;
  box-shadow:inset 0 0 50px rgba(176,138,40,.10) !important;
}

/* ── 代码块状态栏 → 晴空面板 ── */
pre{
  position:relative !important;
  margin:7px 0 !important;
  padding:18px 20px !important;
  border:none !important;
  border-radius:4px !important;
  color:#3a3320 !important;
  background:#f6f0d9 !important;
  box-shadow:inset 0 0 2px rgba(176,138,40,.40),0 3px 10px rgba(0,0,0,.15) !important;
  overflow-x:auto !important;
}
/* 代码块内所有文字统一为清晰深墨蓝色，不锁字号字体、去阴影 */
pre code,pre span,pre div[node="[object Object]"]{
  color:#3a3320 !important;
  background:transparent !important;
  text-shadow:none !important;
}
/* 去除代码块内层一切边框/底色/阴影,文字直接落在纯白 pre 上 */
pre *{
  border:none !important;
  background:transparent !important;
  box-shadow:none !important;
}
/* 四角描金角饰 */
pre::before,pre::after{
  content:'' !important;
  position:absolute !important;
  width:13px !important;height:13px !important;
  border:2px solid #a87f1e !important;
  opacity:.7 !important;
  pointer-events:none !important;
}
pre::before{top:6px !important;left:6px !important;border-right:none !important;border-bottom:none !important;}
pre::after{bottom:6px !important;right:6px !important;border-left:none !important;border-top:none !important;}
/* 平台代码块头栏：弱化 */
pre div[class*="border-b"]{background:transparent !important;border-color:rgba(176,138,40,.3) !important;}

/* ── 正文 markdown 元素（限定在 .markdown-body 内，不污染平台） ── */
.markdown-body p{margin:.55em 0 !important;}
.markdown-body strong,.markdown-body b{color:#b8902e !important;font-weight:700 !important;}
.markdown-body em,.markdown-body i{color:#675b38 !important;}
.markdown-body h1,.markdown-body h2,.markdown-body h3,.markdown-body h4{
  color:#b8902e !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  border-bottom:1px solid rgba(176,138,40,.38) !important;
  padding-bottom:4px !important;
  letter-spacing:.04em !important;
}
.markdown-body hr{
  border:none !important;height:16px !important;
  background:transparent !important;text-align:center !important;
}
.markdown-body hr::after{content:'✦' !important;color:#a87f1e !important;font-size:13px !important;}
.markdown-body blockquote{
  border-left:3px solid #a87f1e !important;
  background:rgba(176,138,40,.09) !important;
  color:#574c30 !important;
  margin:8px 2px !important;padding:6px 12px !important;
  border-radius:0 4px 4px 0 !important;
}
/* 行内代码（单反引号）→ 小标牌 */
.markdown-body :not(pre)>code{
  background:rgba(176,138,40,.12) !important;
  color:#b8902e !important;
  border:1px solid rgba(176,138,40,.32) !important;
  border-radius:3px !important;
  padding:1px 6px !important;
}
.markdown-body ul,.markdown-body ol{padding-left:1.45em !important;}
.markdown-body li{margin:.2em 0 !important;}
.markdown-body li::marker{color:#a87f1e !important;}

/* ── 顶部栏：晴空 ── */
.sticky.w-full.top-0.flex.items-center{
  background:linear-gradient(180deg,#f3ead2,#f3ead2) !important;
  border-bottom:1px solid #b8902e !important;
  box-shadow:0 2px 8px rgba(0,0,0,.16) !important;
}
.sticky.w-full.top-0.flex.items-center .truncate,
.sticky.w-full.top-0.flex.items-center .inline-flex.items-center,
#header-setting-button svg,#ai-model-selector svg,#customized-model-selector svg{color:#9a7826 !important;}

/* ── 底部输入框：晴空 ── */
#ai-chat-input{
  background:linear-gradient(160deg,#f7f2dd,#f3ead2) !important;
  color:#3a3320 !important;
  border:1px solid #b8902e !important;
  border-radius:5px !important;
  font-family:'Georgia','Noto Serif SC',serif !important;
}
#ai-chat-input::placeholder{color:#766943 !important;}


/* ── 记忆卷宗（折叠记忆区） ── */
details.mem{
  margin:7px 0 !important;
  border:1px solid #b8902e !important;
  border-top:2px solid #a87f1e !important;
  border-radius:5px !important;
  background:linear-gradient(160deg,#f6f0d9,#f3ead2) !important;
  box-shadow:0 3px 10px rgba(0,0,0,.16) !important;
  overflow:hidden !important;
}
details.mem>summary{
  cursor:pointer !important;
  list-style:none !important;
  text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:16px !important;
  font-weight:700 !important;
  letter-spacing:3px !important;
  color:#b8902e !important;
  padding:11px 16px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.08),rgba(176,138,40,.20),rgba(176,138,40,.08)) !important;
  border-bottom:1px solid rgba(176,138,40,.30) !important;
}
details.mem>summary::-webkit-details-marker{display:none !important;}
details.mem>summary::before{content:'✦ ' !important;color:#a87f1e !important;}
details.mem>summary::after{content:' ✦' !important;color:#a87f1e !important;}
details.mem .s{padding:14px 16px !important;color:#3a3320 !important;line-height:1.8 !important;}
details.mem .t{
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:15px !important;font-weight:700 !important;letter-spacing:2px !important;
  color:#b8902e !important;text-align:center !important;margin:8px 0 4px !important;
}
details.mem .t::before{content:'━━ ' !important;color:rgba(176,138,40,.45) !important;}
details.mem .t::after{content:' ━━' !important;color:rgba(176,138,40,.45) !important;}
details.mem .s>strong{
  display:block !important;text-align:right !important;
  font-size:12px !important;color:#766943 !important;letter-spacing:1px !important;margin:4px 0 !important;
}
details.mem .s>hr{
  border:none !important;height:1px !important;
  background:linear-gradient(90deg,transparent,rgba(176,138,40,.5),transparent) !important;
  margin:7px 0 !important;
}


/* ── 思维链（折叠推演区） ── */
details.cot{
  margin:7px 0 !important;
  border:1px dashed #b8902e !important;
  border-radius:5px !important;
  background:linear-gradient(165deg,#f7f2dd,#f3ead2) !important;
  box-shadow:0 2px 7px rgba(0,0,0,.10) !important;
  overflow:hidden !important;
}
details.cot>summary{
  cursor:pointer !important;
  list-style:none !important;
  text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:14px !important;
  font-weight:700 !important;
  letter-spacing:2px !important;
  color:#675b38 !important;
  padding:9px 14px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.05),rgba(176,138,40,.14),rgba(176,138,40,.05)) !important;
}
details.cot>summary::-webkit-details-marker{display:none !important;}
details.cot>summary::before{content:'❖ ' !important;color:#a87f1e !important;}
details.cot>summary::after{content:' ❖' !important;color:#a87f1e !important;}
details.cot[open]>summary{border-bottom:1px dashed rgba(176,138,40,.4) !important;}
details.cot p,details.cot ul,details.cot ol{
  margin:.5em 14px !important;
  color:#574c30 !important;
  font-size:13px !important;
  line-height:1.75 !important;
}
details.cot ul,details.cot ol{padding-left:1.5em !important;}
details.cot li{margin:.15em 0 !important;}
details.cot li::marker{color:#a87f1e !important;}
details.cot strong,details.cot b{color:#b8902e !important;}


/* ── 剧情分支（折叠选项区） ── */
details.story-branch{
  margin:7px 0 !important;
  border:1px solid #b8902e !important;
  border-top:2px solid #a87f1e !important;
  border-radius:5px !important;
  background:linear-gradient(160deg,#f6f0d9,#f3ead2) !important;
  box-shadow:0 3px 10px rgba(0,0,0,.16) !important;
  overflow:hidden !important;
}
details.story-branch>summary{
  cursor:pointer !important;
  list-style:none !important;
  text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:16px !important;
  font-weight:700 !important;
  letter-spacing:3px !important;
  color:#b8902e !important;
  padding:11px 16px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.14),rgba(176,138,40,.22),rgba(176,138,40,.14)) !important;
  border-bottom:1px solid rgba(176,138,40,.30) !important;
}
details.story-branch>summary::-webkit-details-marker{display:none !important;}
details.story-branch>summary::before{content:'❧ ' !important;color:#a87f1e !important;}
details.story-branch>summary::after{content:' ❧' !important;color:#a87f1e !important;}
details.story-branch>ul{
  list-style:none !important;
  margin:0 !important;
  padding:12px 14px !important;
}
details.story-branch>ul>li{
  margin:8px 0 !important;
  padding:9px 12px !important;
  color:#3a3320 !important;
  line-height:1.7 !important;
  background:rgba(176,138,40,.07) !important;
  border:1px solid rgba(176,138,40,.22) !important;
  border-left:3px solid #a87f1e !important;
  border-radius:0 4px 4px 0 !important;
  transition:background .15s ease !important;
}
details.story-branch>ul>li:hover{background:rgba(176,138,40,.16) !important;}
details.story-branch>ul>li::marker{content:'' !important;}
details.story-branch>ul>li>strong{
  color:#9a7720 !important;
  font-weight:700 !important;
  margin-right:4px !important;
}


/* ── 状态栏（可折叠数据区） ── */
details.status{margin:7px 0 !important;}
details.status>summary{
  cursor:pointer !important;
  list-style:none !important;
  text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:16px !important;
  font-weight:700 !important;
  letter-spacing:3px !important;
  color:#b8902e !important;
  padding:10px 16px !important;
  border:1px solid #b8902e !important;
  border-radius:5px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.12),rgba(176,138,40,.26),rgba(176,138,40,.12)) !important;
  box-shadow:0 2px 7px rgba(0,0,0,.14) !important;
}
details.status>summary::-webkit-details-marker{display:none !important;}
details.status>summary::before{content:'◈ ' !important;color:#a87f1e !important;}
details.status>summary::after{content:' ◈' !important;color:#a87f1e !important;}
details.status[open]>summary{border-radius:5px 5px 0 0 !important;}
details.status[open]>pre{margin-top:0 !important;}


/* ── 移动端适配 ── */
@media (max-width:600px){
  .markdown-body{padding:10px 11px !important;}
  pre{padding:13px 12px !important;margin:6px 0 !important;}
  pre::before,pre::after{width:10px !important;height:10px !important;}
  details.mem{margin:6px 0 !important;}
  details.mem>summary{font-size:15px !important;letter-spacing:2px !important;padding:9px 12px !important;}
  details.mem .s{padding:11px 12px !important;}
  details.mem .t{font-size:14px !important;letter-spacing:1px !important;}
  details.mem .s>hr{margin:6px 0 !important;}
  .markdown-body h1,.markdown-body h2,.markdown-body h3,.markdown-body h4{letter-spacing:.02em !important;}
  details.cot{margin:6px 0 !important;}
  details.cot>summary{font-size:13px !important;letter-spacing:1px !important;padding:8px 11px !important;}
  details.cot p,details.cot ul,details.cot ol{margin-left:10px !important;margin-right:10px !important;font-size:12.5px !important;}
  details.story-branch{margin:6px 0 !important;}
  details.story-branch>summary{font-size:15px !important;letter-spacing:2px !important;padding:9px 12px !important;}
  details.story-branch>ul{padding:10px 11px !important;}
  details.story-branch>ul>li{padding:8px 10px !important;margin:7px 0 !important;}
  details.status{margin:6px 0 !important;}
  details.status>summary{font-size:15px !important;letter-spacing:2px !important;padding:9px 12px !important;}
}
/* ════════ 晴空学院 · 制卡师平台界面美化 ════════ */
/* 浅蓝描金 · 移动端友好 · 零无限动画(仅交互触发) */

/* ═══ 一、顶部栏 ═══ */
.sticky.w-full.top-0.flex.items-center{
  background:linear-gradient(180deg,#f3ead2 0%,#f3ead2 100%) !important;
  border-bottom:2px solid #a87f1e !important;
  box-shadow:0 2px 10px rgba(0,0,0,.18) !important;
}
#ai-model-selector .group.flex.items-center,#customized-model-selector .group.flex.items-center{
  background:linear-gradient(135deg,#f6f0d9,#f3ead2) !important;
  border:1px solid #b8902e !important;
  border-radius:7px !important;
  box-shadow:0 1px 4px rgba(0,0,0,.12) !important;
  transition:border-color .25s,box-shadow .25s !important;
}
#ai-model-selector .group.flex.items-center:hover,#customized-model-selector .group.flex.items-center:hover{
  border-color:#a87f1e !important;
  box-shadow:0 2px 10px rgba(176,138,40,.25) !important;
}
#ai-model-selector .truncate.text-\[13px\],#customized-model-selector .truncate.text-\[13px\]{
  color:#9a7826 !important;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif !important;
  font-weight:600 !important;letter-spacing:.3px !important;
}
#ai-model-selector .shrink-0.flex.items-center svg,#customized-model-selector .shrink-0.flex.items-center svg{
  color:#a87f1e !important;transition:transform .25s !important;
}
#ai-model-selector .group.flex.items-center:hover .shrink-0.flex.items-center svg,#customized-model-selector .group.flex.items-center:hover .shrink-0.flex.items-center svg{
  transform:translateY(1px) !important;
}
.sticky.w-full.top-0 svg.lucide-clock-8{
  color:#9a7720 !important;transition:transform .3s !important;
}
.sticky.w-full.top-0 svg.lucide-clock-8:hover{transform:rotate(-30deg) !important;}
.sticky.w-full.top-0 span.MuiBadge-dot.md\:hidden{
  background:#a87f1e !important;box-shadow:0 0 6px rgba(176,138,40,.7) !important;
}
.sticky.w-full.top-0 button.MuiIconButton-root:has(svg.lucide-music-2){
  background:rgba(176,138,40,.1) !important;
  border:1px solid #b8902e !important;border-radius:6px !important;
  transition:background .25s,border-color .25s !important;
}
.sticky.w-full.top-0 button.MuiIconButton-root:has(svg.lucide-music-2):hover{
  background:rgba(176,138,40,.2) !important;border-color:#a87f1e !important;
}
.sticky.w-full.top-0 button.MuiIconButton-root svg.lucide-music-2{color:#9a7720 !important;}
.sticky.w-full.top-0 svg:has(use[href="#icon-icon-set"]){
  color:#9a7720 !important;transition:transform .35s !important;
}
.sticky.w-full.top-0 svg:has(use[href="#icon-icon-set"]):hover{transform:rotate(90deg) !important;}
#header-setting-button{
  background:linear-gradient(135deg,#f6f0d9,#f3ead2) !important;
  border:1px solid #b8902e !important;border-radius:7px !important;
  transition:border-color .25s,box-shadow .25s !important;
}
#header-setting-button:hover{
  border-color:#a87f1e !important;box-shadow:0 2px 10px rgba(176,138,40,.25) !important;
}
#header-setting-button svg{color:#9a7720 !important;transition:transform .35s !important;}
#header-setting-button:hover svg{transform:rotate(90deg) !important;}

/* ═══ 二、开场白选择器 ═══ */
div.flex.items-center.cursor-pointer.group[class*="border-gray"]{
  background:linear-gradient(135deg,#f6f0d9,#f3ead2) !important;
  border:1px solid #b8902e !important;border-radius:8px !important;
  box-shadow:0 1px 5px rgba(0,0,0,.12) !important;
  transition:border-color .25s,box-shadow .25s !important;
}
div.flex.items-center.cursor-pointer.group[class*="border-gray"]:hover{
  border-color:#a87f1e !important;box-shadow:0 3px 12px rgba(176,138,40,.22) !important;
}
div.flex.items-center.h-9.cursor-pointer.group svg[data-icon="SlidersH"]{
  color:#a87f1e !important;transition:transform .25s !important;
}
div.flex.items-center.h-9.cursor-pointer.group:hover svg[data-icon="SlidersH"]{
  transform:translateX(2px) !important;
}
div.flex.items-center.h-9.cursor-pointer.group svg[data-icon="ChevronDown"]{
  color:#a87f1e !important;transition:transform .25s !important;
}
div.flex.items-center.h-9.cursor-pointer.group:hover svg[data-icon="ChevronDown"]{
  transform:translateY(2px) !important;
}

/* ═══ 三、按钮栏 ═══ */
#ai-mod-button2 button.MuiButton-root{
  background:linear-gradient(135deg,#f3ead2,#ece2c6) !important;
  border:1px solid #a87f1e !important;border-radius:8px !important;
  color:#9a7826 !important;font-weight:600 !important;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif !important;
  box-shadow:0 2px 7px rgba(0,0,0,.15) !important;
  transition:background .25s,box-shadow .25s,transform .15s !important;
}
#ai-mod-button2 button.MuiButton-root:hover{
  background:linear-gradient(135deg,#f3ead2,#e6dcbe) !important;
  box-shadow:0 4px 14px rgba(176,138,40,.3) !important;transform:translateY(-1px) !important;
}
#ai-mod-button2 button.MuiButton-root:active{transform:translateY(0) scale(.98) !important;}
#ai-mod-button2 button.MuiButton-root svg{color:#a87f1e !important;}

/* ═══ 四、底部栏 ═══ */
.bg-gradient-to-t{
  background:linear-gradient(to top,#f3ead2 0%,rgba(243,235,210,0) 100%) !important;
}
div:has(> div > #ai-chat-input){
  background:linear-gradient(135deg,#f7f2dd,#f3ead2) !important;
  border:2px solid #b8902e !important;border-radius:12px !important;
  box-shadow:0 3px 14px rgba(0,0,0,.16) !important;
  transition:border-color .25s !important;
}
div:has(> div > #ai-chat-input):focus-within{border-color:#a87f1e !important;}
#ai-chat-input{
  background:transparent !important;color:#3a3320 !important;caret-color:#a87f1e !important;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif !important;
}
#ai-chat-input::placeholder{color:#766943 !important;font-style:italic !important;}
#ai-chat-input::selection{background:rgba(176,138,40,.28) !important;color:#8a6e1e !important;}

/* ═══ 五、分页栏(仅颜色/视觉) ═══ */
.MuiPaginationItem-root{
  background:linear-gradient(135deg,#f6f0d9,#f3ead2) !important;
  border:1px solid #b8902e !important;color:#9a7826 !important;
  box-shadow:0 1px 4px rgba(0,0,0,.1) !important;
  transition:background .2s,border-color .2s !important;
}
.MuiPaginationItem-root:hover{
  background:linear-gradient(135deg,#f3ead2,#ece2c6) !important;border-color:#a87f1e !important;
}
.MuiPaginationItem-root.Mui-selected{
  background:linear-gradient(135deg,#a87f1e,#9a7720) !important;
  border-color:#9a7720 !important;color:#2e2716 !important;
}
.MuiPaginationItem-root.Mui-disabled{
  background:#f3ead2 !important;border-color:#e6dcbe !important;color:#7e7148 !important;
}
.MuiPaginationItem-icon{color:#a87f1e !important;}
.MuiStack-root.css-1uwir8f{
  background:rgba(176,138,40,.08) !important;
  border:1px solid #b8902e !important;border-radius:8px !important;
}
.MuiStack-root.css-1uwir8f .MuiBox-root{color:#9a7826 !important;}
.MuiInputBase-input{
  background:#f6f0d9 !important;border:1px solid #b8902e !important;
  border-radius:6px !important;color:#3a3320 !important;
}

/* ═══ 六、评论区 ═══ */
div[class*="w-full"][class*="bg-white"][class*="bottom-0"]{
  background:linear-gradient(170deg,#f7f2dd 0%,#f3ead2 100%) !important;
}
div.text-lg.font-bold{
  color:#9a7826 !important;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif !important;
}
div.text-lg.font-bold::before{content:'◆ ' !important;color:#a87f1e !important;}
p.MuiTypography-body1.text-grey-600{color:#675b38 !important;}
span.MuiRating-iconEmpty svg{color:#a07d22 !important;}
span.MuiRating-iconFilled svg{color:#a87f1e !important;}
span.text-orange-500{color:#9a7720 !important;font-weight:700 !important;}
div.flex.flex-col.border-gray-200{
  background:#f6f0d9 !important;border:1px solid #b8902e !important;border-radius:10px !important;
}
textarea.rc-textarea{
  background:transparent !important;color:#3a3320 !important;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif !important;
}
