/* ════════════ NPC 记录 · details 区块 ════════════ */
details.npc{
  margin:7px 0 !important;
  border:1px solid #b8902e !important;
  border-top:2px solid #a87f1e !important;
  border-radius:5px !important;
  background:linear-gradient(160deg,#f6f0d9,#f3ead2) !important;
  box-shadow:0 3px 10px rgba(0,0,0,.16) !important;
  overflow:hidden !important;
}
details.npc>summary{
  cursor:pointer !important;list-style:none !important;text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:16px !important;font-weight:700 !important;letter-spacing:3px !important;
  color:#b8902e !important;padding:11px 16px !important;
  background:linear-gradient(90deg,rgba(176,138,40,.08),rgba(176,138,40,.20),rgba(176,138,40,.08)) !important;
  border-bottom:1px solid rgba(176,138,40,.30) !important;
}
details.npc>summary::-webkit-details-marker{display:none !important;}
details.npc>summary::before{content:'❂ ' !important;color:#a87f1e !important;}
details.npc>summary::after{content:' ❂' !important;color:#a87f1e !important;}
details.npc .s{padding:6px 14px 12px !important;}
details.npc .s>t{
  display:block !important;text-align:center !important;
  font-family:'KaiTi','STKaiti','Noto Serif SC',serif !important;
  font-size:16px !important;font-weight:700 !important;letter-spacing:2px !important;
  color:#b8902e !important;margin:9px 0 5px !important;
}
details.npc .s>t::before{content:'━ ' !important;color:rgba(176,138,40,.4) !important;}
details.npc .s>t::after{content:' ━' !important;color:rgba(176,138,40,.4) !important;}
details.npc .s>r{
  display:block !important;position:relative !important;
  font-size:15px !important;line-height:1.8 !important;color:#3a3320 !important;
  padding:2px 2px 2px 3px !important;
}
details.npc .s>r.i{
  margin:0 0 0 5px !important;padding-left:12px !important;
  border-left:1.5px solid rgba(176,138,40,.30) !important;
  color:#574c30 !important;font-size:14.5px !important;
}
details.npc .s>hr{
  border:none !important;height:1px !important;
  background:linear-gradient(90deg,transparent,rgba(176,138,40,.5),transparent) !important;
  margin:9px 0 3px !important;
}
@media (max-width:600px){
  details.npc .s{padding-left:11px !important;padding-right:11px !important;}
  details.npc .s>r{font-size:15px !important;}
}

/* 卡牌名/卡组名等标题行的 <b> 加粗 */
